Ui.Script:
GlueDialogTypes["BENILLA_REALMLIST"] = {
	text = "Address of realm list server",
	button1 = OKAY,
	button2 = CANCEL,
	hasEditBox = 1,
	maxLetters = 64,
	OnShow = function()
		GlueDialogEditBox:SetText((BenillaGetRealmlist()));
		GlueDialogEditBox:HighlightText();
	end,
	OnAccept = function()
		BenillaSetRealmlist(GlueDialogEditBox:GetText());
	end,
};
function BenillaRealmlistButton_OnClick()
	PlaySound("gsLoginNewAccount");
	local address, pinned = BenillaGetRealmlist();
	if ( pinned ) then
		GlueDialog_Show("OKAY", "The realmlist is set for this session by the launch, so it stays at "..address..".");
	else
		GlueDialog_Show("BENILLA_REALMLIST");
	end
end
